import random

def run_sequence(transfer, seed, steps=100):
    rng = random.Random(seed)
    accounts = {"a": 500, "b": 300, "c": 200}
    total_before = sum(accounts.values())
    for step in range(steps):
        src, dst = rng.sample(["a", "b", "c"], 2)
        amount = rng.randint(1, 50)
        if accounts[src] >= amount:
            transfer(accounts, src, dst, amount)
            if sum(accounts.values()) != total_before:
                return step, dict(accounts)
    return None, dict(accounts)

def transfer_leaky(accts, src, dst, amount):
    fee = 1
    accts[src] -= amount
    accts[dst] += amount - fee   # fee vanishes from the system

def transfer_honest(accts, src, dst, amount):
    fee = 1
    accts[src] -= amount + fee   # sender pays amount + fee
    accts[dst] += amount

