import unittest, io, re

def fetch_with_retry(fetch, sleeper, attempts=3):
    delay = 1
    for i in range(attempts):
        try:
            return fetch()
        except ConnectionError:
            if i == attempts - 1:
                raise
            sleeper(delay)
            delay *= 2

class TestRetry(unittest.TestCase):
    def test_succeeds_after_two_failures(self):
        calls = {"n": 0}
        def flaky():
            calls["n"] += 1
            if calls["n"] < 3:
                raise ConnectionError("down")
            return "payload"
        delays = []
        result = fetch_with_retry(flaky, delays.append)
        self.assertEqual(result, "payload")
        self.assertEqual(delays, [1, 2])

    def test_gives_up_and_reraises(self):
        def always_down():
            raise ConnectionError("down")
        delays = []
        with self.assertRaises(ConnectionError):
            fetch_with_retry(always_down, delays.append)
        self.assertEqual(delays, [1, 2])

stream = io.StringIO()
unittest.TextTestRunner(stream=stream, verbosity=2).run(
    unittest.defaultTestLoader.loadTestsFromTestCase(TestRetry))
print(re.sub(r"in \d+\.\d+s", "in <elapsed>", stream.getvalue()), end="")

